import { useEffect, useState } from "react";
import { fetchMenu, placeOrder } from "../../api/api";
import { useAuth } from "../../context/AuthContext";

export default function UserPanel() {
  const { user, logout } = useAuth();
  const [menu, setMenu] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    fetchMenu().then(setMenu);
  }, []);

  const add = (item) => setCart([...cart, item]);

  const submit = () => {
    const grouped = {};
    cart.forEach(i => grouped[i.id] = (grouped[i.id] || 0) + 1);

    const items = Object.entries(grouped).map(([id, qty]) => ({
      id: Number(id),
      qty
    }));

    const total = cart.reduce((s, i) => s + i.price, 0);

    placeOrder({
      username: user.username,
      items,
      total,
    });

    setCart([]);
  };

  return (
    <>
      <h2>Welcome {user.username}</h2>
      <button onClick={logout}>Logout</button>

      <div className="grid">
        {menu.map(i => (
          <div key={i.id}>
            <h4>{i.name}</h4>
            <p>₹{i.price}</p>
            <button onClick={() => add(i)}>Add</button>
          </div>
        ))}
      </div>

      <button onClick={submit}>Place Order</button>
    </>
  );
}
